preConditionHook:
// BROOKS'S "BEST" REVERSAL BAR, and the one place in the corpus where an
// M-of-N SCORE is the rule rather than a conjunction. The book says "the best
// bull reversal bars have MORE THAN ONE of the following", so the quality
// terms are counted, not ANDed -- and a count is not reachable by ANDing panes,
// which is why this composite is carried whole under the named-Brooks-setup
// exception rather than split into its four parts.
//
// THE MINIMUM (T00-39, the catalog's ReversalBarMinimum, inlined): a bull body
// OR a close above the bar's midpoint. It is a hard gate, not a quality.
//
// THE THREE QUALITIES, each worth one point (T00-40, T00-41, T00-42):
//   1. the open at or below the prior close, with a bull body closing above
//      that prior close;
//   2. a lower tail between minTailFraction and maxTailFraction of the bar's
//      own range, with the upper tail no more than oppositeTailMax of it --
//      the catalog's ReversalBarTailFraction, inlined at its own defaults;
//   3. little overlap with the prior bar: the shared span is at most
//      maxOverlapFraction of the PRIOR bar's range.
// Source item 5 (the follow-through bar) is DROPPED by the merge pass: it reads
// the bar AFTER the signal bar and so is a look-ahead condition.
//
// TAILS ARE MEASURED FROM THE BODY EDGE, so the same expression is the right
// tail whichever way the bar closed. MinList / MaxList are ACCEPTED for
// tick-grid PRICE operands only, and Open / Close / High / Low are raw prices,
// so the plain ternary stand-in is exact -- the arrangement
// ReversalBarTailFraction and BarOverlapFraction already use. (<algorithm> is
// not among the emitted includes, so no std::min / std::max.)
//
// EVERY COMPARISON IS MULTIPLIED, never a ratio: EL raises a runtime
// divide-by-zero on a doji whose High = Low, and on a zero-range PRIOR bar the
// overlap quality then reduces to "the shared span is at most zero".
//
// BOTH SIDES ARE SCORED IN THE HOOK rather than in the conditions: EasyLanguage
// does not short-circuit, so a score computed inside a condition would run on
// every bar in EL and only on some bars in C++.
// THE TICK is EL's own MinMove / PriceScale, both VERIFIED and per-symbol
// constants for the whole run, written DIVISION-FIRST in both twins so the C++
// reads token for token against its EasyLanguage (README "N ticks",
// TICKSIZE_FINDINGS.md). Read once into a local; it needs no history.
//
// Scratch below is declared in localVariables, not at hook scope: the generator
// only prefixes declared locals, so a hook-scope declaration is a redefinition
// when this rule is placed twice in one strategy. Every one is fully assigned
// each bar before it is read.
tickSz = ctx.MinMove() / ctx.PriceScale();
rng = high[0] - low[0];
prng = high[1] - low[1];
lowerTail = (open[0] < close[0] ? open[0] : close[0]) - low[0];
upperTail = high[0] - (open[0] > close[0] ? open[0] : close[0]);
ovl = (high[0] < high[1] ? high[0] : high[1]) - (low[0] > low[1] ? low[0] : low[1]);
scoreUp = 0;
if (el_le(open[0], close[1] + nearTicks * tickSz) && el_gt(close[0], open[0]) && el_gt(close[0], close[1])) scoreUp = scoreUp + 1;
if (el_ge(lowerTail, minTailFraction * rng) && el_le(lowerTail, maxTailFraction * rng) && el_le(upperTail, oppositeTailMax * rng)) scoreUp = scoreUp + 1;
if (el_le(ovl, maxOverlapFraction * prng)) scoreUp = scoreUp + 1;
scoreDn = 0;
if (el_ge(open[0], close[1] - nearTicks * tickSz) && el_lt(close[0], open[0]) && el_lt(close[0], close[1])) scoreDn = scoreDn + 1;
if (el_ge(upperTail, minTailFraction * rng) && el_le(upperTail, maxTailFraction * rng) && el_le(lowerTail, oppositeTailMax * rng)) scoreDn = scoreDn + 1;
if (el_le(ovl, maxOverlapFraction * prng)) scoreDn = scoreDn + 1;
